cards=[]
shown=0
for i,p in enumerate(data['projects']):
 if p.get('hubParent'): continue # gathered behind a landing room's card (the six STEM workshops behind The STEM Room)
 if p['id']=='baton-box': continue # infrastructure, not a workshop: it gets the banner above the catalog instead
 shown+=1
 links=f'<a class="open" href="{esc(p["entry"] or p["original"])}">'+('Open reference shelf' if p.get('kind')=='reference shelf' else 'Open workshop' if p['bundled'] else 'Visit project')+' <span aria-hidden="true">↗</span></a>'
 if p['download']: links+=f'<a href="{esc(p["download"])}" download>Download ZIP</a>'
 original=f'<a href="{esc(p["original"])}">'+p.get('originLabel', 'Shelf source' if p.get('kind')=='reference shelf' else 'Original website')+' ↗</a>'
 if p['source']: original+=f' · <a href="{esc(p["source"])}">Original source ↗</a>'
 badge='<span class="newbadge">NEW</span>' if p['id'] in NEW_CARDS else ''
 search=' '.join(str(p.get(k,'')) for k in ['title','topic','hook','description','starter']).lower()
 cards.append(f'''<article class="project art-{i}" data-topic="{esc(p['topic'])}" data-search="{esc(search)}" data-id="{esc(p['id'])}" data-offline="{'offline' if p['bundled'] else 'online'}"><div class="illustration"><svg viewBox="0 0 240 174" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round">{art[i % len(art)]}</svg><span class="serial">{shown:02d}</span>{badge}</div><div class="project-body"><p class="eyebrow">{esc(p['topic'])} · {'Reference shelf' if p.get('kind')=='reference shelf' else 'Bundled workshop' if p['bundled'] else 'Linked project'}</p><h3>{esc(p['title'])}</h3><p class="hook">{esc(p['hook'])}</p><p>{esc(p['description'])}</p><p class="starter"><strong>Start here</strong> {esc(p['starter'])}</p><div class="actions">{links}</div><div class="trail-btns"><button type="button" class="trail-btn" data-trail="tried" aria-pressed="false">&#10003; Tried it</button><button type="button" class="trail-btn" data-trail="back" aria-pressed="false">&#9734; Come back</button></div><details><summary>Original home &amp; package details</summary><p>{original}</p><p>{esc(p['detail'])}. {'<span class="chip">&#128218; Reference shelf — packaged for offline browsing; external reading needs internet</span>' if p.get('kind')=='reference shelf' else '<span class="chip">&#11015; Works offline — core activities in the download</span>' if p['bundled'] else '<span class="chip">&#127760; Online project — lives at its original home</span>'}</p></details></div></article>''')
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="Free educational workshops for children and curious adults. Explore computing, robotics, weather, codes, and space. Curated by Steven Powell."><title>Everyday Cool · Portable Workshops for Curious Minds</title><link rel="stylesheet" href="assets/hub.css"><script src="assets/hub.js" defer></script></head><body><a class="skip" href="#collection">Skip to workshops</a><header><a class="brand" href="index.html"><span class="brand-mark" aria-hidden="true">✳</span> Everyday Cool<span class="edition">A GROWING COLLECTION</span></a><nav aria-label="Main navigation"><a href="#collection">Explore</a><a href="learning-paths.html">Learning paths</a><a href="educators.html">Educators</a><a href="homeschool.html">Homeschool</a><a href="documentation.html">Documentation</a><a href="full-index.html">Full Index</a><a href="#contribute">Contribute</a><a href="https://github.com/caeled/everyday-cool">GitHub ↗</a></nav></header><main><section class="hero"><div><p class="eyebrow">FOR OUR CHILDREN. FOR THE CURIOUS.</p><h1>Ordinary curiosity.<br><em>Extraordinary places.</em></h1><p class="subtitle">Portable Workshops for Curious Minds</p><p class="lead">A robot’s next move. A faraway storm. A message hiding in little squares. Pick a question and see where it takes you.</p><div class="hero-actions"><a class="button" href="#collection">Find something cool <span aria-hidden="true">↓</span></a><a class="button" href="arcade.html" style="background:transparent;color:#243747;border:2px solid #243747;padding:11px 18px">Visit Dad's Arcade (to warm up your Neurons) <span aria-hidden="true">→</span></a><a class="text-link" href="https://github.com/caeled/everyday-cool/archive/refs/heads/main.zip">Take the collection with you ↗</a></div><p class="fine">Free to explore. Built with AI assistance. Curated by a human.</p></div><div class="hero-art" style="position:relative"><img src="hero-robot.png" alt="An AI robot juggling the collection’s tiles — code brackets, a question mark, a sparkle, and a sun. AI-generated illustration." style="display:block;width:100%;height:100%;object-fit:contain"><img src="fyre1.png" alt="A fractal flame — a black veil of attractor threads on white. Rendered in Fyre." style="position:absolute;left:23%;top:1%;width:21%;background:#fff;border:3px solid #243747;border-radius:14px;transform:rotate(-7deg)"></div></section>'''+intro_block+whatsnew_block+'''<div class="principles"><span>✳ Free learning, always</span><span>↗ Made to explore and share</span><span>◉ Teaching how systems work</span><span>◎ '''+str(workshops)+''' workshops to carry offline</span></div><section id="collection" aria-labelledby="collection-title"><div class="section-top"><div><p class="eyebrow">THE COLLECTION / START ANYWHERE</p><h2 id="collection-title">What has you curious?</h2></div><p>For kids and adults.<br>No permission to be curious required.</p></div><div class="finder"><div><label for="search">Find a subject or an idea</label><input id="search" type="search" placeholder="Try robots, Antarctica, encryption…" autocomplete="off"></div><div class="filters" role="group" aria-label="Filter workshops by topic"><button type="button" data-filter="all" aria-pressed="true">Everything</button><button type="button" data-filter="Computing" aria-pressed="false">Computing</button><button type="button" data-filter="Robotics" aria-pressed="false">Robotics</button><button type="button" data-filter="Earth &amp; space" aria-pressed="false">Earth &amp; space</button><button type="button" data-filter="Codes &amp; communication" aria-pressed="false">Codes &amp; communication</button><button type="button" data-filter="Reading &amp; reference" aria-pressed="false">Reading &amp; reference</button><button type="button" data-filter="Math" aria-pressed="false">Math</button><button type="button" data-filter="Science" aria-pressed="false">Science</button><button type="button" data-filter="Thinking &amp; decisions" aria-pressed="false">Thinking &amp; decisions</button></div></div><div class="filters" role="group" aria-label="Filter by connection" style="margin:4px 0 8px"><button type="button" data-offline-filter="all" aria-pressed="true">Any connection</button><button type="button" data-offline-filter="offline" aria-pressed="false">Works offline</button><button type="button" data-offline-filter="online" aria-pressed="false">Needs internet</button></div><p id="results" class="fine" role="status">'''+str(len(data['projects']))+''' projects · '''+str(workshops)+''' bundled workshops + '''+str(shelves)+''' reference shelf</p><p id="trail" class="fine" role="status"></p><button type="button" id="trailFilter" class="trail-toggle" aria-pressed="false">Show only my trail</button><div class="projects">'''+''.join(cards)+'''</div><p id="empty" hidden>No matches yet. Try another word or choose Everything.</p><aside class="continuity"><span aria-hidden="true">↗</span><div><h3>A new home. The originals stay.</h3><p>The existing projects remain at their original addresses and continue to be maintained. Everyday Cool is the curated home for this collection and future additions. These are independent copies, updated through review; original websites and source histories are linked on each card.</p></div></aside></section><section id="contribute" class="contribute"><div><p class="eyebrow">OPEN TO IDEAS / CAREFULLY CURATED</p><h2>Something worth<br><em>giving away.</em></h2><p>This collection began with a simple idea: use AI to build things that make someone want to learn. Offer them freely. Keep making them better. Whatever the subject — a network, a storm, a secret code, a robot — every workshop teaches how a system works.</p><p>Curated by Steven Powell. Bring a good question, a clearer explanation, a translation, or a workshop of your own. Develop it in your own fork, then propose it for the collection.</p><a class="button light" href="https://github.com/caeled/everyday-cool/issues/new/choose">Suggest something cool ↗</a></div><div class="steps"><article><span>01</span><h3>Make it useful</h3><p>A real activity, a clear explanation, and sources someone can follow.</p></article><article><span>02</span><h3>Keep it freely accessible</h3><p>No subscriptions, prompt-pack sales, ads, or affiliate funnels in the official collection.</p></article><article><span>03</span><h3>Share it for review</h3><p>Contributions are proposals. Steven decides what joins the official collection.</p></article><a href="CONTRIBUTING.md">Read the contribution guide ↗</a><a href="GOVERNANCE.md">How the collection is curated ↗</a></div></section><section class="license-note"><h2>Use it. Teach from it. Make it yours.</h2><p>Original hub code is MIT; original lessons are CC BY 4.0. Keep credit and applicable notices. Bundled projects and external resources retain their own terms. These free licenses permit commercial reuse; our official collection stays free and independently made forks are not automatically endorsed.</p><div class="actions"><a href="LICENSE">Code license</a><a href="LICENSE-CONTENT.md">Lesson license</a><a href="THIRD-PARTY.md">Credits &amp; external resources</a><a href="README.md">Portable guide</a></div></section><nav class="shareblock" aria-label="Pass it on"><span class="shareblock-label">Pass it on:</span><a href="https://www.facebook.com/sharer/sharer.php?u=https%3A%2F%2Fcaeled.github.io%2Feveryday-cool%2F" target="_blank" rel="noopener">Facebook</a><a href="https://twitter.com/intent/tweet?url=https%3A%2F%2Fcaeled.github.io%2Feveryday-cool%2F&text=Everyday%20Cool%20%E2%80%94%20free%20workshops%20that%20run%20in%20your%20browser" target="_blank" rel="noopener">X</a><a href="https://www.reddit.com/submit?url=https%3A%2F%2Fcaeled.github.io%2Feveryday-cool%2F&title=Everyday%20Cool%20%E2%80%94%20free%20workshops%20that%20run%20in%20your%20browser" target="_blank" rel="noopener">Reddit</a><a href="https://share.flipboard.com/bookmarklet/popout?v=2&url=https%3A%2F%2Fcaeled.github.io%2Feveryday-cool%2F&title=Everyday%20Cool%20%E2%80%94%20free%20workshops%20that%20run%20in%20your%20browser" target="_blank" rel="noopener">Flipboard</a><a href="https://bsky.app/intent/compose?text=Everyday%20Cool%20%E2%80%94%20free%20workshops%20that%20run%20in%20your%20browser%20https%3A%2F%2Fcaeled.github.io%2Feveryday-cool%2F" target="_blank" rel="noopener">Bluesky</a></nav></main><footer><a class="brand" href="#">Everyday Cool <span aria-hidden="true">✳</span></a><p>Steven Powell · Curiosity belongs to everyone.</p><a href="https://github.com/caeled/everyday-cool">Open project ↗</a> · <a href="https://groups.google.com/g/everydaycool" target="_blank" rel="noopener">Join our Forum ↗</a></footer></body></html>'''
